package io.github.finalparadox.entity;
import io.github.finalparadox.ability.GlaivorusAbilityState;import io.github.finalparadox.item.PumpkinMaulItem;import io.github.finalparadox.registry.*;import net.minecraft.core.particles.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.protocol.Packet;import net.minecraft.network.protocol.game.ClientGamePacketListener;import net.minecraft.server.level.*;import net.minecraft.sounds.*;import net.minecraft.world.effect.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.phys.*;import net.minecraftforge.network.NetworkHooks;import java.util.*;
public final class PumpkinHammerSwingEntity extends Entity{private UUID ownerId;private int direction=1;private final Map<UUID,Integer>lastHits=new HashMap<>();public PumpkinHammerSwingEntity(EntityType<PumpkinHammerSwingEntity>t,Level l){super(t,l);noPhysics=true;noCulling=true;}public static boolean hasActive(ServerPlayer o){return !o.serverLevel().getEntitiesOfClass(PumpkinHammerSwingEntity.class,o.getBoundingBox().inflate(16),e->o.getUUID().equals(e.ownerId)).isEmpty();}public static void spawn(ServerPlayer o){if(hasActive(o))return;PumpkinHammerSwingEntity e=new PumpkinHammerSwingEntity(ModEntities.PUMPKIN_HAMMER_SWING.get(),o.serverLevel());e.ownerId=o.getUUID();int side=o.getPersistentData().getInt("finalparadox.pumpkin_hammer_side");e.direction=side==0?1:-1;o.getPersistentData().putInt("finalparadox.pumpkin_hammer_side",side==0?1:0);e.setPos(o.position());o.serverLevel().addFreshEntity(e);tryBarrage(o);}
 private static void tryBarrage(ServerPlayer o){if(!o.isCrouching()||o.getPersistentData().getInt(PumpkinMaulItem.CHARGE_KEY)<20)return;o.getPersistentData().putInt(PumpkinMaulItem.CHARGE_KEY,0);PumpkinBarrageEntity.spawn(o);}
 @Override protected void defineSynchedData(){}@Override public void tick(){super.tick();if(level().isClientSide)return;if(!(level() instanceof ServerLevel s)){discard();return;}ServerPlayer o=ownerId==null?null:s.getServer().getPlayerList().getPlayer(ownerId);if(o==null||!o.isUsingItem()||!o.getUseItem().is(ModItems.PUMPKIN_MAUL.get())){discard();return;}tryBarrage(o);int cycle=(tickCount-1)%16;if(cycle==0&&tickCount>1){direction=-direction;lastHits.clear();s.playSound(null,o.blockPosition(),SoundEvents.UI_TOAST_OUT,SoundSource.PLAYERS,.5F,1.1F);}setPos(o.getX(),o.getY()+.1,o.getZ());setYRot(o.getYRot()+direction*(190-cycle*20));if(cycle<4)return;Vec3 forward=Vec3.directionFromRotation(0,getYRot()).scale(2.5),center=position().add(forward);for(LivingEntity target:s.getEntitiesOfClass(LivingEntity.class,new AABB(center,center).inflate(1.75),e->GlaivorusAbilityState.isHostileTarget(o,e))){int last=lastHits.getOrDefault(target.getUUID(),-20);if(tickCount-last<10)continue;if(target.hurt(o.damageSources().playerAttack(o),11)){lastHits.put(target.getUUID(),tickCount);PumpkinMaulItem.recordHit(o);target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,20,0),o);target.push(forward.x*.4,.2,forward.z*.4);if(o.getRandom().nextBoolean())PumpkinBombEntity.spawn(o,o.position(),.3);s.sendParticles(ParticleTypes.TOTEM_OF_UNDYING,target.getX(),target.getY()+1,target.getZ(),6,0,0,0,.2);s.playSound(null,target.blockPosition(),SoundEvents.HOGLIN_STEP,SoundSource.PLAYERS,1,2);}}s.sendParticles(ParticleTypes.TOTEM_OF_UNDYING,center.x,center.y+1,center.z,1,0,0,0,.2);}
 @Override protected void readAdditionalSaveData(CompoundTag t){if(t.hasUUID("Owner"))ownerId=t.getUUID("Owner");direction=t.getInt("Direction");}@Override protected void addAdditionalSaveData(CompoundTag t){if(ownerId!=null)t.putUUID("Owner",ownerId);t.putInt("Direction",direction);}@Override public Packet<ClientGamePacketListener>getAddEntityPacket(){return NetworkHooks.getEntitySpawningPacket(this);}}
